import sys
from collections import defaultdict

def read_ints():
    return list(map(int, sys.stdin.readline().strip().split()))

n = int(sys.stdin.readline().strip())
s = read_ints()
m = int(sys.stdin.readline().strip())
pipes = [read_ints() for _ in range(m)]

# Create a graph to represent the system
graph = defaultdict(list)
for _ in range(m):
    x, y = read_ints()
    graph[x].append(y)
    graph[y].append(x)

# Check for feasibility
feasible = True
flows = [0] * m

# Try to assign flows to satisfy the constraints
for i in range(n):
    if s[i] > 0:
        # Junction i needs to receive s[i] units of water
        for j in range(m):
            if s[i] > 0:
                flows[j] += 1
                s[i] -= 1
            else:
                break
    elif s[i] < 0:
        # Junction i needs to send out |s[i]| units of water
        for j in range(m):
            if s[i] < 0:
                flows[j] -= 1
                s[i] += 1
            else:
                break

# Check if all constraints are satisfied
for i in range(n):
    if s[i] != 0:
        feasible = False
        break

if feasible:
    print("Possible")
    for flow in flows:
        print(flow)
else:
    print("Impossible")
